#!/usr/bin/env node
// Generates common/data_gen.cpp (species names, types, evolution families, Gen 6/7 location names) from the souldew
// desktop app's data files (native/shared/data: pokeapi.json, locations_gen6.json, locations_gen7.json – see
// ATTRIBUTION.md there: PokéAPI, PKHeX). The generated file is committed; building does not need Node.
//
//   node tools/gen_data.mjs <path to souldew>/native/shared/data
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = process.argv[2];
if (!dir) {
  console.error('usage: node tools/gen_data.mjs <souldew>/native/shared/data');
  process.exit(1);
}
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const MAX = 807;
const p = JSON.parse(readFileSync(join(dir, 'pokeapi.json'), 'utf8'));
const TYPES = ['normal', 'fighting', 'flying', 'poison', 'ground', 'rock', 'bug', 'ghost', 'steel', 'fire', 'water', 'grass',
  'electric', 'psychic', 'ice', 'dragon', 'dark', 'fairy'];
const q = (s) => JSON.stringify(String(s)).replace(/\?\?/g, '?\\?');

function typesFor(id, gen) {
  const g = p.typesGen?.[id];
  if (g) {
    const keys = Object.keys(g).map(Number).filter((k) => k >= gen).sort((a, b) => a - b);
    if (keys.length) return g[keys[0]];
  }
  return p.types[id] || [];
}

const out = [];
out.push('// Generated by tools/gen_data.mjs – do not edit. Sources: PokéAPI (BSD-3-Clause; game data © Nintendo / Game Freak /');
out.push('// The Pokémon Company), PKHeX location texts (GPL-3.0). See NOTICE.md.');
out.push('#include "data.h"');
out.push('namespace sd {');
out.push(`const int kMaxSpecies = ${MAX};`);
for (const lang of ['en', 'de']) {
  out.push(`static const char *const species_${lang}[${MAX + 1}] = {`);
  for (let i = 0; i <= MAX; i++) out.push(`  ${q(p.names[lang][i] || p.names.en[i] || '')},`);
  out.push('};');
}
out.push(`static const unsigned char species_types[${MAX + 1}][2] = {`);
for (let i = 0; i <= MAX; i++) {
  const t = typesFor(i, 6).map((x) => TYPES.indexOf(x));
  out.push(`  {${t[0] ?? 255},${t[1] ?? 255}},`);
}
out.push('};');
out.push(`static const unsigned short species_family[${MAX + 1}] = {`);
const fam = [];
for (let i = 0; i <= MAX; i++) fam.push(p.evolutionChain[i] || 0);
for (let i = 0; i <= MAX; i += 20) out.push('  ' + fam.slice(i, i + 20).join(',') + ',');
out.push('};');
for (const lang of ['en', 'de']) {
  out.push(`static const char *const type_${lang}[18] = {` + TYPES.map((t) => q(p.typeNames[lang][t])).join(',') + '};');
}
for (const gen of [6, 7]) {
  const l = JSON.parse(readFileSync(join(dir, `locations_gen${gen}.json`), 'utf8')).map;
  const ids = Object.keys(l).map(Number).filter((n) => n < 30000).sort((a, b) => a - b);
  out.push(`static const LocName loc${gen}[] = {`);
  for (const id of ids) out.push(`  {${id}, ${q(l[id].en)}, ${q(l[id].de || l[id].en)}},`);
  out.push('};');
  out.push(`static const int loc${gen}_count = ${ids.length};`);
}
out.push(`
const char *speciesName(int id, Lang lang) {
  if (id < 0 || id > kMaxSpecies) return "?";
  return lang == Lang::De ? species_de[id] : species_en[id];
}
int speciesType(int id, int which) {
  if (id < 0 || id > kMaxSpecies || which < 0 || which > 1) return -1;
  int t = species_types[id][which];
  return t == 255 ? -1 : t;
}
int speciesFamily(int id) { return (id < 0 || id > kMaxSpecies) ? 0 : species_family[id]; }
const char *typeName(int t, Lang lang) {
  if (t < 0 || t >= 18) return "";
  return lang == Lang::De ? type_de[t] : type_en[t];
}
const char *locationName(int gen, int id, Lang lang) {
  const LocName *tab = gen >= 7 ? loc7 : loc6;
  int lo = 0, hi = (gen >= 7 ? loc7_count : loc6_count) - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (tab[mid].id == id) return lang == Lang::De ? tab[mid].de : tab[mid].en;
    if (tab[mid].id < id) lo = mid + 1; else hi = mid - 1;
  }
  return nullptr;
}
}  // namespace sd`);
writeFileSync(join(root, 'common', 'data_gen.cpp'), out.join('\n') + '\n');
console.log('common/data_gen.cpp written');
